import{_ as t,o as s,c as n,aN as r}from"./chunks/framework.D31DlcCL.js";const e="/img/math-activity-patterns.svg",g=JSON.parse('{"title":"玩转数学：动手又动脑的趣味数学活动","description":"数学不仅在课本里，更在指尖上。通过剪一剪、拼一拼、找一找，发现数学最真实的美。","frontmatter":{"title":"玩转数学：动手又动脑的趣味数学活动","date":"2026-02-09T12:00:00.000Z","categories":["数学"],"tags":["小学数学","数学活动","实践学习"],"description":"数学不仅在课本里，更在指尖上。通过剪一剪、拼一拼、找一找，发现数学最真实的美。","cover":"/img/math-activity-patterns.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-activity-fun.md","filePath":"posts/primary-math-activity-fun.md","lastUpdated":null}'),i={name:"posts/primary-math-activity-fun.md"};function o(l,a,m,p,h,c){return s(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="玩转数学-动手又动脑的趣味数学活动" tabindex="-1">玩转数学：动手又动脑的趣味数学活动 <a class="header-anchor" href="#玩转数学-动手又动脑的趣味数学活动" aria-label="Permalink to &quot;玩转数学：动手又动脑的趣味数学活动&quot;">​</a></h1><p>你以为数学只是做练习册吗？大错特错！数学是一场华丽的冒险。今天，我们要走出书本，用双手去触摸数学。</p><hr><h2 id="一、-活动-1-图形的-舞步-找规律" tabindex="-1">一、 活动 1：图形的“舞步”（找规律） <a class="header-anchor" href="#一、-活动-1-图形的-舞步-找规律" aria-label="Permalink to &quot;一、 活动 1：图形的“舞步”（找规律）&quot;">​</a></h2><p>大自然里到处都是规律：斑马的条纹、向日葵的叶片。在数学里，规律能帮我们预测未来。</p><p><img src="'+e+'" alt="找规律图解"></p><p><strong>【动手试试】</strong>： 拿出一套积木或彩色纸片，按照“红、黄、蓝、红、黄、蓝”的顺序排一排。</p><ul><li>请问：第 10 个是什么颜色？</li><li><strong>技巧</strong>：这组规律是 3 个一循环，10 除以 3 余 1，所以第 10 个和第 1 个颜色一样，是红色！</li></ul><hr><h2 id="二、-活动-2-剪纸里的对称-轴对称" tabindex="-1">二、 活动 2：剪纸里的对称（轴对称） <a class="header-anchor" href="#二、-活动-2-剪纸里的对称-轴对称" aria-label="Permalink to &quot;二、 活动 2：剪纸里的对称（轴对称）&quot;">​</a></h2><p>拿一张正方形的纸，对折，再对折。在折痕的一侧剪下一个三角形，展开。</p><p><strong>你发现了什么？</strong> 你会得到一个漂亮的对称图形。这就是<strong>轴对称</strong>——折痕就是它的“生命轴”，两边一模一样。</p><hr><h2 id="三、-活动-3-校园里的-步测" tabindex="-1">三、 活动 3：校园里的“步测” <a class="header-anchor" href="#三、-活动-3-校园里的-步测" aria-label="Permalink to &quot;三、 活动 3：校园里的“步测”&quot;">​</a></h2><p>如果我们没有尺子，怎么知道操场有多大？ 我们可以用“步子”来测量！</p><ol><li><strong>量步长</strong>：走 10 步，量一量总距离，再除以 10，得出你的平均步长。</li><li><strong>量距离</strong>：绕着操场走一圈，数数走了多少步。</li><li><strong>算一算</strong>：步数 × 步长 = 操场的周长。</li></ol><hr><h2 id="四、-经典例题-小方块的秘密" tabindex="-1">四、 经典例题：小方块的秘密 <a class="header-anchor" href="#四、-经典例题-小方块的秘密" aria-label="Permalink to &quot;四、 经典例题：小方块的秘密&quot;">​</a></h2><p><strong>题目</strong>：用同样大小的小正方体拼成一个大正方体，最少需要多少个？</p><p><strong>解析</strong>： 很多同学说是 4 个。我们动手摆摆看：</p><ul><li>下层放 4 个（2×2），只能拼出一个大正方形。</li><li>要拼成“方方正正”的立体体，高度也得是 2 个。</li><li>所以是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>×</mo><mn>2</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">2 \\times 2 \\times 2 = 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">8</span></span></span></span>（个）。</li></ul><hr><h2 id="五、-练一练" tabindex="-1">五、 练一练 <a class="header-anchor" href="#五、-练一练" aria-label="Permalink to &quot;五、 练一练&quot;">​</a></h2><ol><li><strong>规律闯关</strong>：○ △ △ ○ △ △ ○ _ _。横线上应该填什么？</li><li><strong>动手拼图</strong>：用 7 块七巧板，你能拼出一个正在跑步的小人吗？拍照记录你的作品吧！</li><li><strong>小小设计师</strong>：用尺子量量你的文具盒，画一个它的俯视图（从上面看下去的样子）。</li></ol><hr><p><em>总结：数学活动能把枯燥的数字变成生动的体验。多动手，你的大脑会变得更聪明！</em></p>',26)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
